describe("extraUnsealPasswords", () => {
  const newPassword = "nova-" + "0".repeat(40);
  const oldPassword = "antiga-" + "0".repeat(40);
  const wrongPassword = "errada-" + "0".repeat(40);
  const unknownPassword = "desconhecida-" + "0".repeat(40);
  const rotatedConfig: SessionConfig = {
    name: "h3-rot",
    password: newPassword,
    extraUnsealPasswords: [oldPassword],
    generateId: () => "fresh",
  };
  const legacyOptions = {
    ...sealDefaults,
    encryption: { ...sealDefaults.encryption, iterations: 1 },
    integrity: { ...sealDefaults.integrity, iterations: 1 },
  };
  const rotatedSetCookie = (res: Response) =>
    decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-rot=([^;]+)/)![1]);

  it("opens a session sealed with an extra password, keeping its id and data", async () => {
    const sealed = await seal(
      { id: "old", createdAt: Date.now(), data: { user: "alice" } },
      oldPassword,
      sealDefaults,
    );
    t.app.get("/rot", async (event) => {
      const session = await useSession(event, rotatedConfig);
      return { id: session.id, data: session.data };
    });

    const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
    expect(await res.json()).toEqual({ id: "old", data: { user: "alice" } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("tries extra passwords in declaration order until one opens the session", async () => {
    const sealed = await seal(
      { id: "old", createdAt: Date.now(), data: {} },
      oldPassword,
      sealDefaults,
    );
    t.app.get("/rot", async (event) => {
      const session = await useSession(event, {
        ...rotatedConfig,
        extraUnsealPasswords: [wrongPassword, oldPassword],
      });
      return { id: session.id };
    });

    const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
    expect(await res.json()).toEqual({ id: "old" });
  });

  it("starts a new session sealed with password when no password opens the cookie", async () => {
    const sealed = await seal(
      { id: "old", createdAt: Date.now(), data: {} },
      unknownPassword,
      sealDefaults,
    );
    t.app.get("/rot", async (event) => {
      const session = await useSession(event, rotatedConfig);
      return { id: session.id };
    });

    const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
    expect(await res.json()).toEqual({ id: "fresh" });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    expect(
      await unseal(rotatedSetCookie(res), newPassword, sealDefaults), // sealed with password
    ).toMatchObject({ id: "fresh" });
  });

  it("reseals a session opened with an extra password with password", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const sealed = await seal(
        { id: "old", createdAt: t0, lastSeenAt: t0, data: {} },
        oldPassword,
        sealDefaults,
      );
      t.app.get("/rot-idle", async (event) => {
        const session = await useSession(event, { ...rotatedConfig, idleTimeout: 60 });
        return { id: session.id };
      });

      // Past half of idleTimeout, so the read slides the window by resealing
      vi.setSystemTime(t0 + 31_000);
      const res = await t.fetch("/rot-idle", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toEqual({ id: "old" });
      const resealed = rotatedSetCookie(res);
      expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({ id: "old" });
      await expect(unseal(resealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    } finally {
      vi.useRealTimers();
    }
  });

  it("opens legacy sessions sealed with an extra password and reseals them", async () => {
    const sealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: {} },
      oldPassword,
      legacyOptions,
    );
    t.app.get("/rot", async (event) => {
      const session = await useSession(event, rotatedConfig);
      return { id: session.id };
    });

    const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
    expect(await res.json()).toEqual({ id: "legacy" });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    expect(await unseal(rotatedSetCookie(res), newPassword, sealDefaults)).toMatchObject({
      id: "legacy",
    });
  });

  it("rejects legacy sessions sealed with an extra password with legacySealFallback: false", async () => {
    const sealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: {} },
      oldPassword,
      legacyOptions,
    );
    t.app.get("/rot", async (event) => {
      const session = await useSession(event, { ...rotatedConfig, legacySealFallback: false });
      return { id: session.id };
    });

    const res = await t.fetch("/rot", { headers: { Cookie: `h3-rot=${sealed}` } });
    expect(await res.json()).toEqual({ id: "fresh" });
  });

  it("expires a session sealed with an extra password past maxAge", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const sealed = await seal(
        { id: "old", createdAt: t0, data: {} },
        oldPassword,
        sealDefaults,
      );
      t.app.get("/rot-max", async (event) => {
        const session = await useSession(event, { ...rotatedConfig, maxAge: 60 });
        return { id: session.id };
      });

      vi.setSystemTime(t0 + 61_000);
      const res = await t.fetch("/rot-max", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toEqual({ id: "fresh" });
    } finally {
      vi.useRealTimers();
    }
  });

  it("expires a session sealed with an extra password past idleTimeout", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const sealed = await seal(
        { id: "old", createdAt: t0, lastSeenAt: t0, data: {} },
        oldPassword,
        sealDefaults,
      );
      t.app.get("/rot-idle-exp", async (event) => {
        const session = await useSession(event, { ...rotatedConfig, idleTimeout: 60 });
        return { id: session.id };
      });

      vi.setSystemTime(t0 + 61_000);
      const res = await t.fetch("/rot-idle-exp", { headers: { Cookie: `h3-rot=${sealed}` } });
      expect(await res.json()).toEqual({ id: "fresh" });
    } finally {
      vi.useRealTimers();
    }
  });

  it("treats an empty extraUnsealPasswords list as no extra passwords", async () => {
    const sealedOld = await seal(
      { id: "old", createdAt: Date.now(), data: {} },
      oldPassword,
      sealDefaults,
    );
    const sealedNew = await seal(
      { id: "current", createdAt: Date.now(), data: {} },
      newPassword,
      sealDefaults,
    );
    t.app.get("/rot-empty", async (event) => {
      const session = await useSession(event, { ...rotatedConfig, extraUnsealPasswords: [] });
      return { id: session.id };
    });

    const current = await t.fetch("/rot-empty", { headers: { Cookie: `h3-rot=${sealedNew}` } });
    expect(await current.json()).toEqual({ id: "current" });
    const old = await t.fetch("/rot-empty", { headers: { Cookie: `h3-rot=${sealedOld}` } });
    expect(await old.json()).toEqual({ id: "fresh" });
  });

  it("rejects an extra password shorter than the minimum length", async () => {
    t.app.get("/rot-short", async (event) => {
      try {
        await useSession(event, { ...rotatedConfig, extraUnsealPasswords: ["curta"] });
        return { error: null };
      } catch (error) {
        return { error: (error as Error).message };
      }
    });

    const res = await t.fetch("/rot-short");
    expect(await res.json()).toEqual({
      error:
        "extraUnsealPasswords: each password must meet the minimum length of the seal options",
    });
  });
});

